<?php declare(strict_types=1);
use Kulturhus\Verein\Settings\NumberingContext;
$nt=static fn(string $source):string=>\Kulturhus\Native\Language\NumberingMessages::text($source,$numberingMessages);
$ns=static fn(mixed $value):string=>is_string($value)||is_int($value)?(string)$value:(is_array($value)?json_encode($value,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE):'');
$nkeep=[];foreach(['number_draft','number_receipt','number_revision','number_history_q','number_history_page','number_revisions_page']as$key)if(is_string($_GET[$key]??null))$nkeep[$key]=$_GET[$key];
$nu=static fn(array $replace=[]):string=>url(['view'=>'settings','tab'=>'numbers']+array_replace($nkeep,$replace));
$nh=static function(array $except=[])use($nkeep):string{$out=hidden('view','settings').hidden('tab','numbers');foreach($nkeep as$key=>$value)if(!in_array($key,$except,true))$out.=hidden($key,$value);return$out;};
$nkinds=['invoice'=>'Rechnungen & Einnahmen','expense'=>'Ausgaben','member'=>'Mitgliedsnummern'];$ndates=['none'=>'Kein Datum','year'=>'Jahr','month'=>'Jahr und Monat'];
$nlabels=['prefix'=>'Präfix','date'=>'Datum','width'=>'Stellen der laufenden Nummer','next'=>'Nächste laufende Nummer','suffix'=>'Suffix'];
$ndescribe=static function(array $rules,?array $context=null)use($nt,$ns,$nkinds,$ndates,$nlabels):void{ ?><details class="general-settings-values"><summary><?= e($nt('Vollständige Werte')) ?></summary><?php foreach($nkinds as$kind=>$label):$rule=is_array($rules[$kind]??null)?$rules[$kind]:[]; ?><section><h4><?= e($nt($label)) ?></h4><dl class="general-settings-description"><?php foreach($nlabels as$key=>$text): ?><dt><?= e($nt($text)) ?></dt><dd><?= e($key==='date'?$nt($ndates[$ns($rule[$key]??'')]??$ns($rule[$key]??'')):$ns($rule[$key]??'')) ?></dd><?php endforeach ?><?php if(isset($context['examples'][$kind])):$example=$context['examples'][$kind]; ?><dt><?= e($nt('Beispielnummer')) ?></dt><dd data-number-example="<?= e($kind) ?>"><?= e($example['exhausted']?$nt('Nummernkreis ausgeschöpft.'):($example['number'].' · '.$nt($example['reserved']?'Bereits vergeben':'Noch nicht vergeben'))) ?></dd><?php endif ?></dl></section><?php endforeach ?></details><?php };
$nreview=static function(array $review)use($nt,$ndescribe):void{ ?><p><?= e($nt('Beispieldatum')) ?>: <strong><?= e($review['input']['date']) ?></strong></p><h4><?= e($nt('Damals gelesener Stand')) ?></h4><?php $ndescribe($review['current']['data']); ?><h4><?= e($nt('Nach Bestätigung gespeicherte Werte')) ?></h4><?php $ndescribe($review['normalized'],$review['numbering_context']); ?><p><?= e($nt('Beispiele für dieses Datum; es wird keine Nummer reserviert oder vergeben.')) ?></p><?php };
$npages=static function(?array $list,string $key)use($nt,$nu,$nh,$ns):void{$raw=$list['page_input']??$_GET[$key]??'1'; ?><form method="get" class="general-settings-page-form"><?= $nh([$key]) ?><label><?= e($nt('Seite')) ?><input class="form-control" name="<?= e($key) ?>" value="<?= e($ns($raw)) ?>" inputmode="numeric"></label><button class="btn btn-outline theme-secondary"><?= e($nt('Seite öffnen')) ?></button><?php if($list): ?><span><?= e($list['total']) ?> · <?= e($list['pages']) ?></span><?php if(($list['page']??null)>1): ?><a class="btn btn-outline theme-secondary" href="<?= e($nu([$key=>(string)($list['page']-1)])) ?>"><?= e($nt('Zurück')) ?></a><?php endif ?><?php if(($list['page']??null)!==null&&$list['page']<$list['pages']): ?><a class="btn btn-outline theme-secondary" href="<?= e($nu([$key=>(string)($list['page']+1)])) ?>"><?= e($nt('Weiter')) ?></a><?php endif ?><?php endif ?></form><?php };
?>
<link rel="stylesheet" href="general-settings-native.css?v=1">
<section class="content general-settings-native" data-native-numbering><header class="page-heading"><h1><?= e($nt('Nummernkreise')) ?></h1></header>
<?php if(!$numberingState)return; ?>
<?php $numberNav=\Kulturhus\Verein\ManagerNavigation::sections(\Kulturhus\Verein\ManagerNavigation::settings(),$workspaceAccess); ?><nav class="general-settings-nav" aria-label="<?= e($nt('Einstellungsbereiche')) ?>"><?php foreach($numberNav as$group): ?><a href="<?= e(url($group['routes'][0][1])) ?>"<?= $group['id']==='rates'?' aria-current="true"':'' ?>><?= e($nt($group['label'])) ?></a><?php endforeach ?></nav>
<?php foreach($numberNav as$group)if($group['id']==='rates'): ?><nav class="general-settings-nav" aria-label="<?= e($nt('Einstellungsbereiche – Unterseiten')) ?>"><?php foreach($group['routes']as[$label,$route]): ?><a href="<?= e(url($route)) ?>"<?= ($route['tab']??'')==='numbers'?' aria-current="page"':'' ?>><?= e($nt($label)) ?></a><?php endforeach ?></nav><?php endif ?>
<section class="card" data-number-current><h2><?= e($nt('Aktueller gespeicherter Stand')) ?></h2><p><?= e($nt('Gespeicherte Fassung')) ?>: <strong data-current-number-version><?= e($numberingState['current']['version']) ?></strong></p>
<?php if($numberingState['current']['version']===0): ?><p><?= e($nt('Die Regeln wurden noch nicht ausdrücklich gespeichert. Bisherige Finanzbelege können ihre bestehende KH-Nummerierung verwenden.')) ?></p><?php endif ?>
<p><?= e($nt('Beispieldatum')) ?>: <?= e($ns($numberingState['date'])) ?></p><?php if($numberingState['error']!==''): ?><p role="alert"><?= e($nt($numberingState['error'])) ?></p><?php endif ?><?php $ndescribe($numberingState['current']['data'],$numberingState['context']); ?><p><?= e($nt('Bestehende Nummern und Dokumente bleiben unverändert. Nur künftige tatsächliche Fachvorgänge vergeben eine Nummer.')) ?></p>
<?php if(!$numberingState['can_write']): ?><p role="status"><?= e($nt('Lesender Finanzzugriff. Nummernregeln können hier nicht geändert werden.')) ?></p><?php endif ?></section>
<?php foreach($numberingState['errors']as$kind=>$message): ?><p role="alert" data-number-error="<?= e($kind) ?>"><?= e($nt($message)) ?></p><?php endforeach ?>
<?php if($numberingState['receipt']):$nr=$numberingState['receipt']; ?><section class="card" data-number-original><h2><?= e($nt('Nummernbestätigung')) ?></h2><dl><dt><?= e($nt('Vorgang')) ?></dt><dd><code data-number-original-key><?= e($nr['key']) ?></code></dd><dt><?= e($nt('Gespeicherte Fassung')) ?></dt><dd><?= e($nr['result']['version']) ?></dd><dt><?= e($nt('Konto')) ?></dt><dd><?= e($nr['actor_id']) ?></dd><dt><?= e($nt('Zeitpunkt')) ?></dt><dd><?= e($nr['created_at']) ?></dd><dt>SHA-256</dt><dd><code><?= e($nr['sha256']) ?></code></dd></dl><a class="btn btn-outline theme-secondary" data-number-original-download data-navigation-native href="<?= e($nu(['number_original'=>$nr['key']])) ?>"><?= e($nt('Original-JSON herunterladen')) ?></a>
<h3><?= e($nt('Eingaben')) ?></h3><p><?= e($nt('Beispieldatum')) ?>: <?= e($nr['input']['date']) ?></p><?php $ndescribe($nr['input']['data']); ?><h3><?= e($nt('Prüfung')) ?></h3><?php $nreview($nr['review']); ?><h3><?= e($nt('Tatsächliches Ergebnis')) ?></h3><?php $ndescribe($nr['result']['data']); ?><?php if($numberingState['can_write']): ?><a class="btn btn-solid theme-primary" href="<?= e(url(['view'=>'settings','tab'=>'numbers'])) ?>"><?= e($nt('Weitere Nummernregeln bearbeiten')) ?></a><?php endif ?></section><?php endif ?>
<?php if($numberingDraft&&$numberingDraft['accepted']===null):$nd=$numberingDraft; ?>
<section class="card" data-number-compose><h2><?= e($nt('Ungespeicherter Entwurf')) ?></h2><p><?= e($nt('Entwurfskennung')) ?>: <code data-number-key><?= e($nd['key']) ?></code></p><a class="btn btn-outline theme-secondary" data-number-check href="<?= e($nu(['number_draft'=>$nd['id'],'number_receipt'=>$nd['key']])) ?>"><?= e($nt('Ursprünglichen Nummernausgang lesend prüfen')) ?></a>
<?php if($nd['pending']): ?><p role="status"><?= e($nt('Prüfung noch nicht bestätigt. Zuerst den ursprünglichen Ausgang lesen.')) ?></p><?php endif ?>
<?php if($numberingState['can_write']): ?>
<form method="post" data-number-edit><?= csrf().hidden('action','numbering-native').hidden('number_draft',$nd['id']) ?>
<label class="general-settings-field"><?= e($nt('Beispieldatum')) ?><input class="form-control" name="number_date" value="<?= e($ns($nd['input']['date']??'')) ?>" placeholder="YYYY-MM-DD" inputmode="numeric" required></label><p><?= e($nt('Beispiele für dieses Datum; es wird keine Nummer reserviert oder vergeben.')) ?></p>
<?php foreach($nkinds as$kind=>$title):$rule=is_array($nd['input']['data'][$kind]??null)?$nd['input']['data'][$kind]:[]; ?><fieldset data-numbering-rule="<?= e($kind) ?>"><legend><?= e($nt($title)) ?></legend><div class="general-settings-grid"><?php foreach($nlabels as$key=>$label):$value=$ns($rule[$key]??'');$id='number-'.$kind.'-'.$key; ?><label class="general-settings-field" for="<?= e($id) ?>"><span><?= e($nt($label)) ?></span><?php if($key==='date'): ?><select class="form-control" id="<?= e($id) ?>" name="data[<?= e($kind) ?>][date]"><?php if(!array_key_exists($value,$ndates)): ?><option value="<?= e($value) ?>" selected><?= e($value) ?></option><?php endif ?><?php foreach($ndates as$code=>$dateLabel): ?><option value="<?= e($code) ?>" <?= $value===$code?'selected':'' ?>><?= e($nt($dateLabel)) ?></option><?php endforeach ?></select><?php else: ?><input class="form-control" id="<?= e($id) ?>" name="data[<?= e($kind) ?>][<?= e($key) ?>]" value="<?= e($value) ?>" <?= in_array($key,['width','next'],true)?'inputmode="numeric" required':'' ?>><?php if(in_array($key,['prefix','suffix'],true)): ?><small><?= e($nt('Zeichenhöchstzahl')) ?>: <?= $key==='prefix'?30:20 ?></small><?php else: ?><small>1 – <?= $key==='width'?'9':'999999999' ?></small><?php endif ?><?php endif ?></label><?php endforeach ?></div></fieldset><?php endforeach ?>
<div class="general-settings-actions"><button class="btn btn-solid theme-primary" name="number_intent" value="preview"><?= e($nt('Nummernregeln prüfen')) ?></button><button class="btn btn-outline theme-secondary" name="number_intent" value="current" formnovalidate><?= e($nt('Aktuelle Zähler bewusst prüfen')) ?></button><button class="btn btn-outline theme-secondary" name="number_intent" value="discard" formnovalidate><?= e($nt('Entwurf verwerfen')) ?></button></div></form>
<?php else:$ndescribe(is_array($nd['input']['data']??null)?$nd['input']['data']:[]);endif ?>
<?php if($nd['review']): ?><section data-number-review><h3><?= e($nt('Geprüfter Vorschlag')) ?></h3><?php $nreview($nd['review']); ?><p><?= e($nt('Eine neue Prüfung übernimmt nur die aktuelle Fassung. Gewünschte Regeln, nächste Werte und Beispieldatum bleiben erhalten.')) ?></p>
<?php if($numberingState['can_write']&&!$nd['pending']&&!$nd['conflicted']&&!NumberingContext::issues($nd['review'])): ?><form method="post" data-number-accept><?= csrf().hidden('action','numbering-native').hidden('number_draft',$nd['id']).hidden('number_key',$nd['key']).hidden('number_review',$nd['review']['hash']).hidden('number_intent','accept') ?><label class="general-settings-check"><input type="checkbox" name="number_approved" value="1" required><span><?= e($nt('Die vollständigen Nummernregeln und das Beispieldatum sind geprüft.')) ?></span></label><button class="btn btn-solid theme-primary"><?= e($nt('Geprüfte Nummernregeln bestätigen')) ?></button></form><?php endif ?></section><?php endif ?>
<?php if($nd['previous']): ?><details data-number-previous><summary><?= e($nt('Frühere Nummernvorschläge')) ?></summary><?php foreach($nd['previous']as$earlier): ?><section><code><?= e($earlier['key']) ?></code><p><?= e($nt('Beispieldatum')) ?>: <?= e($ns($earlier['input']['date']??'')) ?></p><?php $ndescribe(is_array($earlier['input']['data']??null)?$earlier['input']['data']:[]);if($earlier['review'])$nreview($earlier['review']); ?></section><?php endforeach ?></details><?php endif ?></section><?php endif ?>
<?php if($numberingDraftIndex): ?><section class="card"><h2><?= e($nt('Entwürfe')) ?></h2><ul><?php foreach($numberingDraftIndex as$row): ?><li><a href="<?= e($nu(['number_draft'=>$row['id']])) ?>"><?= e($nt('Entwurf öffnen')) ?> <code><?= e($row['key']) ?></code></a></li><?php endforeach ?></ul></section><?php endif ?>
<details class="card" data-number-history <?= \Kulturhus\Verein\Web\UiPanels::historyRequested($_GET)?'open':'' ?>><summary><?= e($nt('Private Bestätigungen')) ?></summary><form method="get" class="general-settings-actions" data-live-search-page="number_history_page"><?= $nh(['number_history_q','number_history_page']) ?><label><?= e($nt('Bestätigungen durchsuchen')) ?><input class="form-control" name="number_history_q" value="<?= e($ns($_GET['number_history_q']??'')) ?>"></label><button class="btn btn-outline theme-secondary"><?= e($nt('Suchen')) ?></button></form><?php $npages($numberingState['history'],'number_history_page'); ?><?php if($numberingState['history']): ?><ul><?php foreach($numberingState['history']['rows']as$row): ?><li><a href="<?= e($nu(['number_receipt'=>$row['request_key']])) ?>"><code><?= e($row['request_key']) ?></code> · <?= e($row['version']) ?> · <?= e($row['created_at']) ?></a></li><?php endforeach ?></ul><?php if(!$numberingState['history']['rows']&&$numberingState['history']['error']===''): ?><p><?= e($nt('Keine passende Bestätigung.')) ?></p><?php endif ?><?php endif ?></details>
<section class="card" data-number-revisions><h2><?= e($nt('Gespeicherte Fassungen')) ?></h2><p><?= e($nt('Frühere Fassungen enthalten die tatsächlich gespeicherten Werte. Eine damalige Vorschau oder ausdrückliche Annahme wird nicht nachträglich behauptet.')) ?></p><?php $npages($numberingState['revisions'],'number_revisions_page'); ?><?php if($numberingState['revisions']): ?><ul><?php foreach($numberingState['revisions']['rows']as$row): ?><li><a href="<?= e($nu(['number_revision'=>(string)$row['version']])) ?>"><?= e($nt('Fassung öffnen')) ?> <?= e($row['version']) ?> · <?= e($row['happened_at']) ?> · <?= e($row['actor_id']) ?></a></li><?php endforeach ?></ul><?php endif ?>
<?php if($numberingState['revision']):$revision=$numberingState['revision']; ?><section data-number-revision><h3><?= e($nt('Frühere Originalfassung')) ?> <?= e($revision['version']) ?></h3><p><?= e($revision['actor_id']) ?> · <?= e($revision['happened_at']) ?></p><code><?= e($revision['sha256']) ?></code><a class="btn btn-outline theme-secondary" data-number-revision-download data-navigation-native href="<?= e($nu(['number_revision_original'=>(string)$revision['version']])) ?>"><?= e($nt('Original-JSON herunterladen')) ?></a><?php $ndescribe($revision['data']); ?></section><?php endif ?></section>
</section>
